<template><AppShell><PageHeader :title="title" subtitle="Normalized operational master data."></PageHeader><form class="card mb-6 grid gap-3 p-5 md:grid-cols-3" @submit.prevent="create"><FormInput label="Name" v-model="form.name"/><FormInput v-if="resource==='vehicles'" label="Plate Number" v-model="form.plate_number"/><FormInput v-if="resource==='products'" label="SKU" v-model="form.sku"/><button class="btn-primary self-end">Create</button></form><DataTable :columns="columns" :rows="records.data"/></AppShell></template>
<script>import { Inertia } from '@inertiajs/inertia'; import AppShell from '../../Components/AppShell.vue'; import PageHeader from '../../Components/PageHeader.vue'; import DataTable from '../../Components/DataTable.vue'; import FormInput from '../../Components/FormInput.vue'; export default{components:{AppShell,PageHeader,DataTable,FormInput},props:{resource:String,title:String,records:Object},data(){return{form:{name:'',is_active:true}}},computed:{columns(){return[{key:'name',label:'Name'},{key:'is_active',label:'Active'}]}},methods:{create(){Inertia.post('/'+this.resource,this.form)}}}</script>